import re


def eval_expression(expr: str):
    """+, -, *, /、括弧、負の数に対応した式の計算"""

    class Parser:
        number_pattern = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)")

        def __init__(self, text):
            self.text = text
            self.pos = 0

        def skip_spaces(self):
            while self.pos < len(self.text) and self.text[self.pos].isspace():
                self.pos += 1

        def parse(self):
            value = self.parse_add_sub()
            self.skip_spaces()

            if self.pos != len(self.text):
                raise ValueError(
                    f"不正な文字があります: {self.text[self.pos]!r}"
                )

            return value

        # 加算・減算
        def parse_add_sub(self):
            value = self.parse_mul_div()

            while True:
                self.skip_spaces()

                if self.pos >= len(self.text):
                    break

                op = self.text[self.pos]
                if op not in "+-":
                    break

                self.pos += 1
                right = self.parse_mul_div()

                if op == "+":
                    value += right
                else:
                    value -= right

            return value

        # 乗算・除算
        def parse_mul_div(self):
            value = self.parse_unary()

            while True:
                self.skip_spaces()

                if self.pos >= len(self.text):
                    break

                op = self.text[self.pos]
                if op not in "*/":
                    break

                self.pos += 1
                right = self.parse_unary()

                if op == "*":
                    value *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= right

            return value

        # 単項の + / -
        def parse_unary(self):
            self.skip_spaces()

            if self.pos < len(self.text) and self.text[self.pos] in "+-":
                op = self.text[self.pos]
                self.pos += 1
                value = self.parse_unary()
                return value if op == "+" else -value

            return self.parse_primary()

        # 数値または括弧
        def parse_primary(self):
            self.skip_spaces()

            if self.pos < len(self.text) and self.text[self.pos] == "(":
                self.pos += 1
                value = self.parse_add_sub()
                self.skip_spaces()

                if self.pos >= len(self.text) or self.text[self.pos] != ")":
                    raise ValueError("閉じ括弧 ')' がありません")

                self.pos += 1
                return value

            match = self.number_pattern.match(self.text, self.pos)
            if not match:
                raise ValueError(
                    f"数値または '(' が必要です: 位置 {self.pos}"
                )

            token = match.group()
            self.pos = match.end()

            return float(token) if "." in token else int(token)

    if not isinstance(expr, str):
        raise TypeError("expr は文字列で指定してください")

    return Parser(expr).parse()
